            'ui.tutorial.lessonsHelp': 'Lessons appear when their mechanics become relevant.',
            'ui.tutorial.progress': 'Lesson {current} of {total}',
            'ui.tutorial.read': 'Read',
            'ui.tutorial.new': 'New',
            'ui.tutorial.unlockedOne': 'A new help lesson is available.',
            'ui.tutorial.unlockedMany': '{count} new help lessons are available.',
            'ui.tutorial.lesson.welcome.title': 'Welcome',
            'ui.tutorial.lesson.welcome.content': 'Explore, learn your limits, and grow stronger. The Help menu reveals short lessons as their mechanics become relevant.',
            'ui.tutorial.lesson.welcome.tip': 'Tip: Help never pauses progress permanently; close it and replay any unlocked lesson later.',
            'ui.tutorial.lesson.cards.title': 'Reading Creature Cards',
            'ui.tutorial.lesson.cards.content': 'A card shows condition, spirit, hunger, row, disposition, and traits. Actor selects who acts; Mark selects who or what they act upon. Expand details when you need exact equipment or capacity.',
            'ui.tutorial.lesson.cards.tip': 'Tip: compact cards are for scanning. Details are for decisions.',
            'ui.tutorial.lesson.actions.title': 'Actors, Targets, and Attempts',
            'ui.tutorial.lesson.actions.content': 'Choose living actors, mark legal targets, then choose an intent. Requirements and costs are previews, not guaranteed success. A committed attempt may fail in the Scene Feed and still spend its turn and cost.',
            'ui.tutorial.lesson.actions.tip': 'Tip: clear actors or targets separately when a many-to-many plan is not what you intended.',
            'ui.tutorial.lesson.map.title': 'Travel and the Review Map',
            'ui.tutorial.lesson.map.content': 'The 3 by 3 play surface moves the party. The Review Map plans through known territory: track quests, inspect known tiles, filter markers, zoom, pan, and recenter. Unknown tiles remain unknown.',
            'ui.tutorial.lesson.map.tip': 'Tip: danger and quest layers are planning clues, not remote action buttons.',
            'ui.tutorial.lesson.combat.title': 'Combat Turns',
            'ui.tutorial.lesson.combat.content': 'Combat follows the visible turn order. Manual companions wait for your choice; autonomous companions choose through the same legal action rules. Skip and Flee remain available when no target works.',
            'ui.tutorial.lesson.combat.tip': 'Tip: acting earlier is not always safer—rows, condition, and enemy reach matter.',
            'ui.tutorial.lesson.rows.reach.title': 'Rows and Reach',
            'ui.tutorial.lesson.rows.reach.content': 'Rows protect back-line creatures from close physical contact. Ranged, flying, social, and special techniques use different reach. A protected physical attempt can be committed and fail narratively instead of becoming a system error.',
            'ui.tutorial.lesson.rows.reach.tip': 'Tip: use social reach, ranged equipment, movement, or allies when the front row blocks contact.',
            'ui.tutorial.lesson.group.actions.title': 'Group Actions',
            'ui.tutorial.lesson.group.actions.content': 'Select multiple actors or targets before choosing an intent. Group and multi-target actions charge each participating actor once. Multi-target Fight begins weak per target and improves through practice or an authored area technique.',
            'ui.tutorial.lesson.group.actions.tip': 'Tip: spreading one novice attack over many targets reduces its effect on each target.',
            'ui.tutorial.lesson.items.title': 'Items and Holdings',
            'ui.tutorial.lesson.items.content': 'Holdings separates equipment, pack, living containers, and ground objects. Consumables show implemented effects and legal targets. Quest items required by an active quest cannot be casually sold or dropped.',
            'ui.tutorial.lesson.items.tip': 'Tip: healing items can target living companions in and out of combat.',
            'ui.tutorial.lesson.equipment.title': 'Equipment',
            'ui.tutorial.lesson.equipment.content': 'Equipment changes statistics and can enable combat techniques. Slot and body compatibility are checked before equipping. Removing an item removes its reversible bonus and any technique eligibility it supplied.',
            'ui.tutorial.lesson.equipment.tip': 'Tip: compare the preview and technique tags, not only the item price.',
            'ui.tutorial.lesson.quests.title': 'Quests and Turn-In',
            'ui.tutorial.lesson.quests.content': 'Objectives move from active to ready for turn-in. Track a quest or its turn-in on the Review Map; physical rewards are claimed only at the declared giver or destination unless the quest explicitly completes automatically.',
            'ui.tutorial.lesson.quests.tip': 'Tip: the tracked marker changes from the objective to the turn-in destination when appropriate.',
            'ui.tutorial.lesson.companion.behavior.title': 'Companion Behavior',
            'ui.tutorial.lesson.companion.behavior.content': 'Duty is a companion contribution, Stance is risk posture, and Control decides who chooses. Deterministic autonomy works offline; provider-assisted control falls back safely. Recruitment history seeds the initial behavior but does not lock it.',
            'ui.tutorial.lesson.companion.behavior.tip': 'Tip: Guard, Scout, Support, and Gatherer have visible exploration benefits even without AI.',
            'ui.tutorial.lesson.perks.title': 'Perk Frontier',
            'ui.tutorial.lesson.perks.content': 'The Perk Frontier shows only choices available now. Hidden future or incompatible perks are not previews. Each level adds one choice; selected effects are reversible through the confirmed free alpha respec.',
            'ui.tutorial.lesson.perks.tip': 'Tip: choose for the actions you actually use; unavailable branches stay hidden until relevant.',
            'ui.tutorial.lesson.containment.title': 'Containment',
            'ui.tutorial.lesson.containment.content': 'Eating can place a creature in a living container when reach, size, willingness, and capacity permit. Containment tracks progress, vitality, and release eligibility. Digest and Release act on a specific contained creature.',
            'ui.tutorial.lesson.containment.tip': 'Tip: Release preserves a living creature only while its current state remains releasable.',
            'ui.tutorial.lesson.recovery.title': 'Defeat and Recovery',
            'ui.tutorial.lesson.recovery.content': 'Recovery mode determines what follows terminal defeat. Regeneration returns you home; Ghost Pilgrimage limits interaction until a shrine restores you; Hardcore ends the run. Fleeing is not death.',
            'ui.tutorial.lesson.recovery.tip': 'Tip: companions finish an active fight before the player recovery outcome settles.',
            'ui.tutorial.welcome.title': 'Welcome',
            'ui.tutorial.welcome.content': 'You are wild in a strange living world. Explore, learn your limits, and grow stronger. Choose your risks carefully.',
            'ui.tutorial.combat.title': 'Combat',
            'ui.tutorial.combat.content': 'In combat, you take turns with enemies and allies. Use Fight, Talk, Eat, Play, Feed, or Flee. Select actors, mark targets, choose an intent, then commit group plans. Each intent owns its reach: social actions can cross rows, while physical attempts may fail and explain why in the Scene Feed.',
            'ui.tutorial.feast.title': 'Eat',
            'ui.tutorial.feast.content': 'Eat weakened targets to hold them safely. Capacity matters, and optional modules can add alternate outcomes.',
            'ui.tutorial.party.title': 'Party',
