            'ui.tutorial.done': 'Listo',
            'ui.tutorial.close': 'Cerrar',
            'ui.tutorial.reset': 'Reiniciar',
            'ui.tutorial.lessons': 'Lecciones de ayuda',
            'ui.tutorial.lessonsHelp': 'Las lecciones aparecen cuando sus mecanicas se vuelven relevantes.',
            'ui.tutorial.progress': 'Leccion {current} de {total}',
            'ui.tutorial.read': 'Leida',
            'ui.tutorial.new': 'Nueva',
            'ui.tutorial.unlockedOne': 'Hay una nueva leccion de ayuda disponible.',
            'ui.tutorial.unlockedMany': 'Hay {count} nuevas lecciones de ayuda disponibles.',
            'ui.tutorial.lesson.welcome.title': 'Bienvenida',
            'ui.tutorial.lesson.welcome.content': 'Explora, aprende tus limites y hazte mas fuerte. El menu de Ayuda revela lecciones breves cuando sus mecanicas se vuelven relevantes.',
            'ui.tutorial.lesson.welcome.tip': 'Consejo: la Ayuda no detiene tu progreso; cierrala y vuelve a cualquier leccion desbloqueada.',
            'ui.tutorial.lesson.cards.title': 'Leer las cartas de criatura',
            'ui.tutorial.lesson.cards.content': 'Una carta muestra condicion, animo, hambre, fila, disposicion y rasgos. Actor elige quien actua; Marcar elige sobre quien o que actua. Abre los detalles para ver equipo o capacidad exactos.',
            'ui.tutorial.lesson.cards.tip': 'Consejo: las cartas compactas sirven para revisar; los detalles sirven para decidir.',
            'ui.tutorial.lesson.actions.title': 'Actores, objetivos e intentos',
            'ui.tutorial.lesson.actions.content': 'Elige actores vivos, marca objetivos legales y luego elige una intencion. Requisitos y costos son previsiones, no garantias. Un intento confirmado puede fallar en la escena y aun gastar turno y costo.',
            'ui.tutorial.lesson.actions.tip': 'Consejo: limpia actores u objetivos por separado si no querias un plan de muchos contra muchos.',
            'ui.tutorial.lesson.map.title': 'Viaje y mapa de revision',
            'ui.tutorial.lesson.map.content': 'La superficie de 3 por 3 mueve al grupo. El mapa de revision permite planear por territorio conocido: sigue misiones, inspecciona casillas, filtra marcadores, acerca, desplaza y centra. Las casillas desconocidas siguen desconocidas.',
            'ui.tutorial.lesson.map.tip': 'Consejo: peligro y misiones son pistas para planear, no botones de accion remota.',
            'ui.tutorial.lesson.combat.title': 'Turnos de combate',
            'ui.tutorial.lesson.combat.content': 'El combate sigue el orden visible. Los companeros manuales esperan tu eleccion; los autonomos eligen con las mismas reglas legales. Saltar y Huir siguen disponibles cuando ningun objetivo funciona.',
            'ui.tutorial.lesson.combat.tip': 'Consejo: actuar antes no siempre es mas seguro; importan filas, condicion y alcance enemigo.',
            'ui.tutorial.lesson.rows.reach.title': 'Filas y alcance',
            'ui.tutorial.lesson.rows.reach.content': 'Las filas protegen a la retaguardia del contacto fisico cercano. Ataques a distancia, vuelo, acciones sociales y tecnicas especiales tienen distinto alcance. Un intento fisico protegido puede confirmarse y fallar en la narracion sin convertirse en error del sistema.',
            'ui.tutorial.lesson.rows.reach.tip': 'Consejo: usa alcance social, equipo a distancia, movimiento o aliados cuando la primera fila bloquea el contacto.',
            'ui.tutorial.lesson.group.actions.title': 'Acciones grupales',
            'ui.tutorial.lesson.group.actions.content': 'Selecciona varios actores u objetivos antes de elegir una intencion. Las acciones grupales cobran una vez a cada actor participante. Luchar contra varios empieza debil por objetivo y mejora con practica o una tecnica de area.',
            'ui.tutorial.lesson.group.actions.tip': 'Consejo: repartir un ataque novato entre muchos objetivos reduce su efecto en cada uno.',
            'ui.tutorial.lesson.items.title': 'Objetos y pertenencias',
            'ui.tutorial.lesson.items.content': 'Pertenencias separa equipo, mochila, contenedores vivos y objetos del suelo. Los consumibles muestran efectos implementados y objetivos legales. Los objetos requeridos por una mision activa no se venden ni tiran por accidente.',
            'ui.tutorial.lesson.items.tip': 'Consejo: los objetos curativos pueden apuntar a companeros vivos dentro y fuera de combate.',
            'ui.tutorial.lesson.equipment.title': 'Equipo',
            'ui.tutorial.lesson.equipment.content': 'El equipo cambia estadisticas y puede habilitar tecnicas de combate. Se revisan ranura y compatibilidad corporal. Quitar un objeto elimina su bono reversible y la elegibilidad de tecnica que aportaba.',
            'ui.tutorial.lesson.equipment.tip': 'Consejo: compara la vista previa y etiquetas de tecnica, no solo el precio.',
            'ui.tutorial.lesson.quests.title': 'Misiones y entrega',
            'ui.tutorial.lesson.quests.content': 'Los objetivos pasan de activos a listos para entregar. Sigue la mision o su entrega en el mapa; las recompensas fisicas se reclaman con el dador o destino declarado salvo que la mision sea automatica.',
            'ui.tutorial.lesson.quests.tip': 'Consejo: el marcador seguido cambia del objetivo al destino de entrega cuando corresponde.',
            'ui.tutorial.lesson.companion.behavior.title': 'Comportamiento de companeros',
            'ui.tutorial.lesson.companion.behavior.content': 'Funcion es la contribucion, Actitud es la postura de riesgo y Control decide quien elige. La autonomia determinista funciona sin conexion; la IA vuelve a ella si falla. El reclutamiento inicia el comportamiento, pero no lo bloquea.',
            'ui.tutorial.lesson.companion.behavior.tip': 'Consejo: Guardia, Explorador, Apoyo y Recolector dan beneficios visibles incluso sin IA.',
            'ui.tutorial.lesson.perks.title': 'Opciones actuales de mejoras',
            'ui.tutorial.lesson.perks.content': 'Las opciones muestran solo mejoras disponibles ahora. Las futuras o incompatibles quedan ocultas. Cada nivel da una eleccion; sus efectos se revierten con el reinicio gratuito y confirmado del alfa.',
            'ui.tutorial.lesson.perks.tip': 'Consejo: elige para las acciones que usas; las ramas no disponibles permanecen ocultas.',
            'ui.tutorial.lesson.containment.title': 'Contencion',
            'ui.tutorial.lesson.containment.content': 'Comer puede colocar una criatura en un contenedor vivo si alcance, tamano, voluntad y capacidad lo permiten. Se registran progreso, vitalidad y posibilidad de liberar. Digerir y Liberar apuntan a una criatura especifica.',
            'ui.tutorial.lesson.containment.tip': 'Consejo: Liberar conserva viva a la criatura solo mientras su estado permita liberarla.',
            'ui.tutorial.lesson.recovery.title': 'Derrota y recuperacion',
            'ui.tutorial.lesson.recovery.content': 'El modo de recuperacion decide que ocurre tras una derrota terminal. Regenerar devuelve al hogar; Peregrinaje fantasma limita interacciones hasta un santuario; Extremo termina la partida. Huir no es morir.',
            'ui.tutorial.lesson.recovery.tip': 'Consejo: los companeros terminan una pelea activa antes de resolver la recuperacion del jugador.',
            'ui.tutorial.welcome.title': 'Bienvenida',
            'ui.tutorial.welcome.content': 'Eres salvaje en un mundo vivo y extrano. Explora, aprende tus limites y hazte mas fuerte. Elige tus riesgos con cuidado.',
            'ui.tutorial.combat.title': 'Combate',
            'ui.tutorial.combat.content': 'En combate, tomas turnos con enemigos y aliados. Usa Luchar, Hablar, Comer, Jugar, Alimentar o Huir. Selecciona actores, marca objetivos, elige una intencion y confirma planes grupales. Cada intencion tiene su propio alcance: las acciones sociales pueden cruzar filas, mientras que los intentos fisicos pueden fallar y explicarse en la Scene Feed.',
            'ui.tutorial.feast.title': 'Comer',
            'ui.tutorial.feast.content': 'Come objetivos debilitados para retenerlos de forma segura. La capacidad importa, y los modulos opcionales pueden agregar resultados alternativos.',
            'ui.tutorial.party.title': 'Grupo',
            'ui.tutorial.party.content': 'Recluta criaturas dispuestas, asigna roles, elige ordenes de IA y gestiona quien actua durante exploracion o combate.',
            'ui.tutorial.ready.title': 'Listo',
            'ui.tutorial.ready.content': 'Empieza a explorar cuando estes listo. Usa los paneles de mapa, grupo y criaturas para mantener el flujo manejable.',
            'ui.menu.edition': 'Edicion tactica oscura',
            'ui.menu.contentDefault': 'El contenido seguro esta activado por defecto',
